"""``operator`` / ``operator_param`` / ``operator_prop`` 的读写。

三条容易踩的：
* **``operator`` 表没有逻辑删除** → 所有查询不带 ``is_enabled``，
  但 **``operator_param``/``operator_prop`` 的批插 SQL 不含该列**，靠 DDL 默认值 'Y'。
* 列表查询**没有任何 ORDER BY** —— 顺序由 PG 堆序决定。不要加 ORDER BY（那是行为变更）。
* ``id`` 列是 ``GENERATED BY DEFAULT``（可显式插负数，V4/V5 的种子就靠这个）；
  而 ``operator_param.id`` 是 ``GENERATED ALWAYS``，**不能显式插 id**。
"""

from __future__ import annotations

from typing import Any, Iterable, Optional

from infrastructure.db.kb import connection
from shared.errors.api import KbStoreError

from infrastructure.db.rows import rows as _rows


def _visible_clause(visible_range: Optional[str], emp_no: str) -> tuple[str, list[Any]]:
    """可见性过滤（``selectByCondition`` 的三分支）。

    ``visible_range`` 为 None 时是「公开的 + 我自己私有的」；指定时只按它过滤
    （PRIVATE 分支**只看 created_by**，不额外限 private）。
    """
    if visible_range == 'public':
        return " AND visible_range = 'public'", []
    if visible_range == 'private':
        return ' AND created_by = %s', [emp_no]
    return " AND (visible_range = 'public' OR (visible_range = 'private' AND created_by = %s))", [emp_no]


def _common_filters(operator_ids: Optional[Iterable], keyword: Optional[str],
                    module: Optional[str], org_id: Optional[str]) -> tuple[str, list[Any]]:
    sql = ''
    params: list[Any] = []
    if operator_ids:
        sql += ' AND id = ANY(%s)'
        params.append(list(operator_ids))
    if module:
        sql += ' AND module = %s'
        params.append(module)
    if org_id:
        sql += ' AND org_id = %s'
        params.append(org_id)
    if keyword:
        # 算子列表的搜索框显示的是「当前语言的名字」：英文界面下显示 name_en，
        # 只匹配 name 会让英文名搜不到。用 ILIKE 让大小写都不敏感，
        # ``ESCAPE`` 把用户输入的 % / _ 当字面量（模糊匹配仍由两端的 % 提供）。
        pattern = '%' + str(keyword).replace('\\', '\\\\').replace('%', '\\%').replace('_', '\\_') + '%'
        sql += (" AND (name ILIKE %s ESCAPE '\\' OR COALESCE(name_en, '') ILIKE %s ESCAPE '\\')")
        params.extend([pattern, pattern])
    return sql, params


def search_operators(operator_ids, visible_range, keyword, module, org_id, emp_no,
                     limit: int, offset: int) -> list[dict]:
    """``selectByCondition(..., page)`` 的分页查询。**无 ORDER BY**。"""
    where = " WHERE 1=1"
    params: list[Any] = []
    extra, extra_params = _common_filters(operator_ids, keyword, module, org_id)
    where += extra
    params += extra_params
    visible_sql, visible_params = _visible_clause(visible_range, emp_no)
    where += visible_sql
    params += visible_params
    with connection() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                f'SELECT * FROM operator{where} LIMIT %s OFFSET %s',
                params + [limit, offset])
            return _rows(cursor)


def count_operators(operator_ids, visible_range, keyword, module, org_id, emp_no) -> int:
    where = " WHERE 1=1"
    params: list[Any] = []
    extra, extra_params = _common_filters(operator_ids, keyword, module, org_id)
    where += extra
    params += extra_params
    visible_sql, visible_params = _visible_clause(visible_range, emp_no)
    where += visible_sql
    params += visible_params
    with connection() as conn:
        with conn.cursor() as cursor:
            cursor.execute(f'SELECT count(*) FROM operator{where}', params)
            return int(cursor.fetchone()[0])


def select_published_by_condition(operator_ids, keyword, module, org_id, emp_no) -> list[dict]:
    """``selectByCondition(operatorIds, keyword, module)``：**强制 is_published=1**，
    且 ``operatorIds`` 为空时直接返回空列表（不是「不过滤」——那是另一个重载的行为）。"""
    if not operator_ids:
        return []
    where = " WHERE is_published"
    params: list[Any] = [list(operator_ids)]
    where += ' AND id = ANY(%s)'
    extra, extra_params = _common_filters(None, keyword, module, org_id)
    where += extra
    params += extra_params
    visible_sql, visible_params = _visible_clause(None, emp_no)
    where += visible_sql
    params += visible_params
    with connection() as conn:
        with conn.cursor() as cursor:
            cursor.execute(f'SELECT * FROM operator{where}', params)
            return _rows(cursor)


def select_by_module(module: str, org_id: Optional[str] = None) -> list[dict]:
    """``selectByModule``：**不校验 is_published**、也不做可见性过滤（画布用这条）。"""
    sql = "SELECT * FROM operator WHERE module = %s"
    params: list[Any] = [module]
    if org_id:
        sql += ' AND org_id = %s'
        params.append(org_id)
    with connection() as conn:
        with conn.cursor() as cursor:
            cursor.execute(sql, params)
            return _rows(cursor)


def select_by_id(operator_id) -> Optional[dict]:
    with connection() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                "SELECT * FROM operator WHERE id = %s", (operator_id,))
            rows = _rows(cursor)
    return rows[0] if rows else None


def select_by_name(name: str, org_id: Optional[str] = None) -> list[dict]:
    """按中文名查重（英文名**不查**）。"""
    sql = "SELECT * FROM operator WHERE name = %s"
    params: list[Any] = [name]
    if org_id:
        sql += ' AND org_id = %s'
        params.append(org_id)
    with connection() as conn:
        with conn.cursor() as cursor:
            cursor.execute(sql, params)
            return _rows(cursor)


def select_by_creator(operator_id, emp_no: str) -> Optional[dict]:
    """``selectOperatorByCreator``：只有创建者本人能操作（publish 家族的前置）。"""
    with connection() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                "SELECT * FROM operator WHERE id = %s AND created_by = %s",
                (operator_id, emp_no))
            rows = _rows(cursor)
    return rows[0] if rows else None


def list_params_by_operator_ids(operator_ids: Iterable) -> dict[Any, list[dict]]:
    """``selectParamsByOperatorIds``：按 operatorId 分组。"""
    ids = list(operator_ids)
    if not ids:
        return {}
    with connection() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                "SELECT * FROM operator_param WHERE operator_id = ANY(%s) "
                'ORDER BY id',
                (ids,))
            grouped: dict[Any, list[dict]] = {}
            for row in _rows(cursor):
                grouped.setdefault(row['operator_id'], []).append(row)
            return grouped


def list_props_by_operator_ids(operator_ids: Iterable) -> dict[Any, dict[str, str]]:
    ids = list(operator_ids)
    if not ids:
        return {}
    with connection() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                "SELECT operator_id, prop_name, prop_value FROM operator_prop "
                "WHERE operator_id = ANY(%s)",
                (ids,))
            grouped: dict[Any, dict[str, str]] = {}
            for operator_id, prop_name, prop_value in cursor.fetchall():
                grouped.setdefault(operator_id, {})[prop_name] = prop_value
            return grouped


def select_ids_by_format(fmt: str) -> list[int]:
    """按 ``prop_value LIKE '%fmt%'`` 查（子串匹配，不是集合成员判断）。

    ⚠️ 这里**不加 DISTINCT**：重复 id 进了
    ``IN (...)`` 不影响结果，加 DISTINCT 只是白白多一次排序。
    """
    with connection() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                "SELECT operator_id FROM operator_prop "
                "WHERE prop_name = 'support_format' AND prop_value LIKE %s",
                ('%' + fmt + '%',))
            return [int(row[0]) for row in cursor.fetchall()]


def select_by_org_id(operator_id, org_id: Optional[str]) -> Optional[dict]:
    """``selectOperatorByOrgId``：``org_id`` 为空时**不加该条件**。

    删库/删算子的第一道门用的就是它 —— 注意它**不校验 created_by**，
    所以 org 为空时任何人都能删。
    """
    sql = "SELECT * FROM operator WHERE id = %s"
    params: list[Any] = [operator_id]
    if org_id:
        sql += ' AND org_id = %s'
        params.append(org_id)
    with connection() as conn:
        with conn.cursor() as cursor:
            cursor.execute(sql, params)
            rows = _rows(cursor)
    return rows[0] if rows else None


def list_params_by_operator_id(operator_id) -> list[dict]:
    """``selectParamsByOperatorId``（单数）：``GET /operator/{id}`` 用。"""
    with connection() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                "SELECT * FROM operator_param WHERE operator_id = %s "
                'ORDER BY id',
                (operator_id,))
            return _rows(cursor)


def list_props_by_operator_id(operator_id) -> dict[str, str]:
    """``OperatorPropDao.selectByOperatorId``：``{prop_name: prop_value}``。"""
    with connection() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                "SELECT prop_name, prop_value FROM operator_prop "
                "WHERE operator_id = %s",
                (operator_id,))
            return {name: value for name, value in cursor.fetchall()}


# ----------------------------------------------------------------------
# 状态翻转与删除
#
# 这几条都是「先 selectById 再 updateById/deleteById」：
# * ``selectById`` **查不到时按 NPE 处理**（→ 0001）
# * ``updateById`` 会把 ``updated_at`` 刷成当前时间、``updated_by`` 刷成当前用户
# * ``deleteById`` 是**物理删除**（连同 param/prop）
# ----------------------------------------------------------------------


def _fill_last_updated(cursor, operator_id, emp_no: Optional[str]) -> None:
    """两处填充：``updated_at`` 与 ``updated_by``。"""
    if emp_no:
        cursor.execute(
            'UPDATE operator SET updated_at = NOW(), updated_by = %s '
            "WHERE id = %s",
            (emp_no, operator_id))
    else:
        cursor.execute(
            'UPDATE operator SET updated_at = NOW() '
            "WHERE id = %s",
            (operator_id,))


def require_by_id(operator_id) -> dict:
    """按 id 取行；查不到抛错（→ 0001 服务器错误）。"""
    row = select_by_id(operator_id)
    if row is None:
        raise KbStoreError(KbStoreError.NOT_FOUND, f'operator {operator_id} not found')
    return row


def set_publish_status(operator_id, status: int, emp_no: Optional[str]) -> None:
    with connection() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                "UPDATE operator SET is_published = %s WHERE id = %s",
                (bool(status), operator_id))
            _fill_last_updated(cursor, operator_id, emp_no)


def set_public_status(operator_id, visible_range: str, emp_no: Optional[str]) -> None:
    with connection() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                'UPDATE operator SET visible_range = %s '
                "WHERE id = %s",
                (visible_range, operator_id))
            _fill_last_updated(cursor, operator_id, emp_no)


def update_system(operator_id, emp_no: Optional[str]) -> None:
    """更新 system 标记：先确认行存在（查不到就抛错），再置 ``system=1``。"""
    require_by_id(operator_id)
    with connection() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                "UPDATE operator SET system = TRUE WHERE id = %s",
                (operator_id,))
            _fill_last_updated(cursor, operator_id, emp_no)


def delete_operator(operator_id) -> None:
    """``deleteOperator``：**物理删除**算子及其参数/属性。"""
    with connection() as conn:
        with conn.cursor() as cursor:
            cursor.execute('DELETE FROM operator_param WHERE operator_id = %s', (operator_id,))
            cursor.execute('DELETE FROM operator_prop WHERE operator_id = %s', (operator_id,))
            cursor.execute('DELETE FROM operator WHERE id = %s', (operator_id,))
